        for r in range(h):
            for c in range(w):
                if grid[r][c] == color and not visited[r][c]:
                    comp = []
                    stack = [(r, c)]
                    while stack:
                        rr, cc = stack.pop()
                        if not visited[rr][cc]:
                            visited[rr][cc] = True
                            comp.append((rr, cc))
                            grid_at = grid[rr][cc]
                            if grid_at == color:
                                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                                    nr, nc = rr+dr, cc+dc
                                    if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                                        stack.append((nr, nc))

                    bbox = (min(c[0] for c in comp), max(c[0] for c in comp),
                            min(c[1] for c in comp), max(c[1] for c in comp))
                    if bbox:
                        r1, r2, c1, c2 = bbox
                        for rr in range(r1, r2+1):
                            for cc in range(c1, c2+1):
                                result[rr][cc] = color

    # Handle 0s - fill with majority adjacent non-0, non-9
    for _ in range(10):
        for r in range(h):
            for c in range(w):
                if result[r][c] == 0:
                    adj = []
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
