                    if adj:
                        cnt = Counter(adj)
                        most = cnt.most_common()
                        for cval, n in reversed(most):
                            if cval != 9:
                                result[r][c] = cval
                                break
                        else:
                            result[r][c] = most[0][0] if most else 0

